"use strict";(self.webpackChunkajaymore=self.webpackChunkajaymore||[]).push([["8899"],{2840(e,t,n){n.r(t),n.d(t,{assets:()=>l,contentTitle:()=>r,default:()=>u,frontMatter:()=>i,metadata:()=>a,toc:()=>d});var a=n(747),s=n(4848),o=n(8453);let i={title:"10 pounds lighter",date:new Date("2014-03-20T18:53:48.000Z"),authors:["ajay"],tags:["Health","Diet","self control","weight loss"],description:"Regular exercise and ability to do heavy physical activity whenever required wasn\u2019t enough to keep away that excess fat around my belly. My diet is moderately regulated, but sometimes it just goes berserk, chocolates and sweets are my greatest adversaries when it comes to losing weight. A hundred times I had tried dieting and failed.\u2026",mdx:{format:"md"}},r,l={authorsImageUrls:[void 0]},d=[];function h(e){let t={a:"a",blockquote:"blockquote",br:"br",p:"p",...(0,o.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(t.p,{children:"Regular exercise and ability to do heavy physical activity whenever required wasn\u2019t enough to keep away that excess fat around my belly. My diet is moderately regulated, but sometimes it just goes berserk, chocolates and sweets are my greatest adversaries when it comes to losing weight. A hundred times I had tried dieting and failed. It\u2019s not that dieting never worked, but the thing was I had such great expectations, that I was stubborn to have it all or nothing. So whenever I hit a plateau I just quit. Recently it became so worse that I just quit the effort of keeping my weight under check. And as expected this had a dire effect. With weeks and months passing by my weight kept on mounting. The weight that fluctuated between 68-70kg, was now 73 and it didn\u2019t feel right.\xa0"}),"\n","\n",(0,s.jsx)(t.p,{children:"Back from a trip to Goa, I was quite pumped up to lose that extra flab and feel good about myself. Received some very useful tips from my close friends and felt the time was right to just do it. Below is my journey of four weeks that helped me lose more than 10 pounds about 5kg to be more exact. The only thing different this time was that I had better tools, better control and better knowledge of my situation."}),"\n",(0,s.jsxs)(t.blockquote,{children:["\n",(0,s.jsxs)(t.p,{children:["Week 1",(0,s.jsx)(t.br,{}),"\nFirst week is usually neutral. There is enough will power in reserve, and although body and mind provides a good deal of resistance the will power counter balances it."]}),"\n"]}),"\n",(0,s.jsxs)(t.p,{children:["Diet:",(0,s.jsx)(t.br,{}),"\nBreakfast: 1 raw egg, oatmeal, green tea.",(0,s.jsx)(t.br,{}),"\nLunch: 1/2 chicken tandoori or sprout-vegetable salad.",(0,s.jsx)(t.br,{}),"\nEve-snacks: omelette with brown bread",(0,s.jsx)(t.br,{}),"\nDinner: sprout salad"]}),"\n",(0,s.jsx)(t.p,{children:"Supplements : 1 vitamin-mineral capsule (Revital) after dinner."}),"\n",(0,s.jsxs)(t.p,{children:["Workout:",(0,s.jsx)(t.br,{}),"\nBody weight exercises in the morning, with focus on upper and lower body on alternate days.",(0,s.jsx)(t.br,{}),"\n20-30min walk after dinner."]}),"\n",(0,s.jsxs)(t.p,{children:["Lifestyle changes:",(0,s.jsx)(t.br,{}),"\nMeditation 10min, morning and evening.",(0,s.jsx)(t.br,{}),"\nA good 8 hour sleep."]}),"\n",(0,s.jsxs)(t.p,{children:["Challenges:",(0,s.jsx)(t.br,{}),"\nConvincing friends, colleagues, family of my intentions, and confronting the ensuing embarrassment. There is not a soul in the world except for you who thinks dieting would be successful.",(0,s.jsx)(t.br,{}),"\nWeekends normally ruin your resolve, I chose to stay vigilant. I exercised moderately on weekends to remind myself of the goal ahead."]}),"\n",(0,s.jsxs)(t.blockquote,{children:["\n",(0,s.jsxs)(t.p,{children:["Week 2",(0,s.jsx)(t.br,{}),"\nI could already see changes happening, I did feel lighter. Overall lethargy of the body was reduced to a great extent. Muscles felt more in control. The Monday felt awesome."]}),"\n"]}),"\n",(0,s.jsxs)(t.p,{children:["Diet changes:",(0,s.jsx)(t.br,{}),"\nEve-snacks: omelette was replaced with no-sugar fruit juice. I freaked over omelette being fried & oily, thus me consuming more than necessary calories.",(0,s.jsx)(t.br,{}),"\nDinner: 2 spoon Apple cider juice before sleep, apple cider is known for reducing obesity, I thought of giving it a try."]}),"\n",(0,s.jsxs)(t.p,{children:["Workout changes:",(0,s.jsx)(t.br,{}),"\nSwimming after office hours for about half an hour."]}),"\n",(0,s.jsxs)(t.p,{children:["Lifestyle changes:",(0,s.jsx)(t.br,{}),"\nMeditation 15min, morning and evening."]}),"\n",(0,s.jsxs)(t.p,{children:["Challenges:",(0,s.jsx)(t.br,{}),"\nAvoiding those innocent moments where someone offers you a chocolate or a pastry or some other sweet. Sometimes I felt I was being too conscious, but it helped. I didn\u2019t fall prey. I knew I wouldn\u2019t last for long if this continued, but I wanted to fight it out as long as I could."]}),"\n",(0,s.jsxs)(t.blockquote,{children:["\n",(0,s.jsxs)(t.p,{children:["Week 3",(0,s.jsx)(t.br,{}),"\nThe weight had reduced considerably. However I felt very low on my overall energy level. It was becoming increasingly difficult to improve my strength training routine. I always felt short of inspiration and energy. Also I had hit the plateau, most visible fat had reduced and it was difficult to spot improvement by just looking at the mirror. The week was long and arduous. However the results were incredible. By the weeks\u2019 end I had made a considerable progress."]}),"\n"]}),"\n",(0,s.jsxs)(t.p,{children:["Diet changes:",(0,s.jsx)(t.br,{}),"\nEating nuts almonds/walnuts whenever possible throughout the day.",(0,s.jsx)(t.br,{}),"\nEve-snacks: eating almonds, no fruit juice.",(0,s.jsx)(t.br,{}),"\nDinner: 2 spoon peanut butter with sprouts."]}),"\n",(0,s.jsxs)(t.p,{children:["Workout changes:",(0,s.jsx)(t.br,{}),"\nDaily walk of 30min after dinner."]}),"\n",(0,s.jsxs)(t.p,{children:["Lifestyle changes:",(0,s.jsx)(t.br,{}),"\nMeditation 20min, morning and evening."]}),"\n",(0,s.jsxs)(t.p,{children:["Challenges:",(0,s.jsx)(t.br,{}),"\nI was considered for a serious project work which demanded more time, and more focused work. This new task drained a lot of vital energy and I felt exhausted on almost all days. Sometimes I would straight away go to sleep after coming from office so that I didn\u2019t indulge myself on happy food due to lack of energy. Once I had a nice nap of about 20-30 min. I would wake up and go about the tasks remaining for the day."]}),"\n",(0,s.jsxs)(t.blockquote,{children:["\n",(0,s.jsxs)(t.p,{children:["Week 4",(0,s.jsx)(t.br,{}),"\nI knew very well that my diet has to end, and it should end on a happy note. I shouldn\u2019t regret it being broken. There shouldn\u2019t be any feeling of guilt when it broke. So I had to gradually switch to eating normal. Also indulge at times but with total awareness of where I was headed to. This week I was merrier as I felt privileged to try stuff that was forbidden for 3 weeks. Now I could observe myself being conscious all the time about whatever went inside my stomach. I was polite in refusing, whenever some delicacy was given due indulgence and it was time to stop."]}),"\n"]}),"\n",(0,s.jsxs)(t.p,{children:["Diet changes:",(0,s.jsx)(t.br,{}),"\nBreakfast: 1 raw egg, oatmeal, green tea, with freedom to try any other on alternate days.",(0,s.jsx)(t.br,{}),"\nLunch: 1/2 chicken tandoori or sprout-vegetable salad or any other meal that is just about enough and did not make me feel bloated.",(0,s.jsx)(t.br,{}),"\nEve-snacks: omelette with brown bread",(0,s.jsx)(t.br,{}),"\nDinner: normal meal, no rice."]}),"\n",(0,s.jsxs)(t.p,{children:["Workout changes:",(0,s.jsx)(t.br,{}),"\nStrength training in morning, brisk walk in the evening."]}),"\n",(0,s.jsxs)(t.p,{children:["Lifestyle changes:",(0,s.jsx)(t.br,{}),"\nMeditation 10min, morning and evening."]}),"\n",(0,s.jsxs)(t.blockquote,{children:["\n",(0,s.jsxs)(t.p,{children:["Closing note:",(0,s.jsx)(t.br,{}),"\nDieting is challenging stuff, but we should aspire to see the change in ourselves. Everyone\u2019s body type is unique and experimentation is the key. Experiment, observe and make changes, repeat this process for as long as is possible until you are sure what works best for you. It\u2019s a wonderful feeling when you are lighter, when the clothes just fit and don\u2019t make any effort to contain the body within. Overall it requires one to change the entire routine one follows and be absolutely religious about it. I would confess I didn\u2019t adhere 100% to what I had planned but 100% was always the goal, so don\u2019t feel disheartened if you fail at some time, but make sure you learn from it. The goal should be 100% effort always. Health is a lifelong habit, so make amendments to your life such that they stick with your forever. Get in the habit of reading good articles and research related to wellbeing. Learn yoga and meditation, they will be your guiding light for the days to come."]}),"\n"]}),"\n",(0,s.jsxs)(t.p,{children:["Couple of videos that helped me visualize what I wanted to achieve.",(0,s.jsx)(t.br,{}),"\n",(0,s.jsx)(t.a,{href:"http://embed.ted.com/talks/lang/en/sandra_aamodt_why_dieting_doesn_t_usually_work.html",children:"http://embed.ted.com/talks/lang/en/sandra_aamodt_why_dieting_doesn_t_usually_work.html"})]}),"\n",(0,s.jsx)(t.p,{children:(0,s.jsx)(t.a,{href:"http://embed.ted.com/talks/lang/en/matt_cutts_try_something_new_for_30_days.html",children:"http://embed.ted.com/talks/lang/en/matt_cutts_try_something_new_for_30_days.html"})})]})}function u(e={}){let{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(h,{...e})}):h(e)}},8453(e,t,n){n.d(t,{R:()=>i,x:()=>r});var a=n(6540);let s={},o=a.createContext(s);function i(e){let t=a.useContext(o);return a.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:i(e.components),a.createElement(o.Provider,{value:t},e.children)}},747(e){e.exports=JSON.parse('{"permalink":"/blog/2014/03/21/10-pounds-lighter","source":"@site/blog/2014-03-21-10-pounds-lighter/index.md","title":"10 pounds lighter","description":"Regular exercise and ability to do heavy physical activity whenever required wasn\u2019t enough to keep away that excess fat around my belly. My diet is moderately regulated, but sometimes it just goes berserk, chocolates and sweets are my greatest adversaries when it comes to losing weight. A hundred times I had tried dieting and failed.\u2026","date":"2014-03-20T18:53:48.000Z","tags":[{"inline":true,"label":"Health","permalink":"/blog/tags/health"},{"inline":true,"label":"Diet","permalink":"/blog/tags/diet"},{"inline":true,"label":"self control","permalink":"/blog/tags/self-control"},{"inline":true,"label":"weight loss","permalink":"/blog/tags/weight-loss"}],"readingTime":5.71,"hasTruncateMarker":true,"authors":[{"name":"Ajay More","title":"Maintainer of ajaymore.in","url":"https://github.com/ajaymore","imageURL":"https://avatars.githubusercontent.com/u/7659804?v=4","key":"ajay","page":null}],"frontMatter":{"title":"10 pounds lighter","date":"2014-03-20T18:53:48.000Z","authors":["ajay"],"tags":["Health","Diet","self control","weight loss"],"description":"Regular exercise and ability to do heavy physical activity whenever required wasn\u2019t enough to keep away that excess fat around my belly. My diet is moderately regulated, but sometimes it just goes berserk, chocolates and sweets are my greatest adversaries when it comes to losing weight. A hundred times I had tried dieting and failed.\u2026","mdx":{"format":"md"}},"unlisted":false,"prevItem":{"title":"Where is my weekend?","permalink":"/blog/2014/04/13/where-is-my-weekend"},"nextItem":{"title":"Atheism 2.0","permalink":"/blog/2014/03/19/atheism-2-0"}}')}}]);